INPUT_DIR = '/inputs'
import json
from decimal import Decimal, ROUND_HALF_UP
from datetime import date

def load(name):
    try:
        with open(f"{INPUT_DIR}/{name}", encoding="utf-8") as fh:
            return json.load(fh)
    except FileNotFoundError:
        return None

def dec(v):
    if v is None:
        return None
    if isinstance(v, str) and v.strip().lower() == "unreadable":
        return None
    try:
        return Decimal(str(v))
    except Exception:
        return None

def money(d):
    return str(d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

def kl1(d):
    return str(d.quantize(Decimal("0.1"), rounding=ROUND_HALF_UP))

bill = load("bill.json") or {}
tariff = load("tariff.json") or {}
history = load("history.json")

subtotal = vat = total = None
consumption = dec(bill.get("consumption_kl"))
tiers = tariff.get("water_tiers") or []
fixed = tariff.get("fixed_charges") or []
vat_rate = dec(tariff.get("vat_rate"))

if consumption is not None and tiers:
    lines = []
    ok = True
    for t in tiers:
        f = dec(t.get("from_kl"))
        to = t.get("to_kl")
        to = dec(to) if to is not None else None
        rate = dec(t.get("rate_per_kl"))
        if f is None or rate is None:
            ok = False
            break
        upper = to if to is not None else consumption
        band = min(consumption, upper) - f
        if band < 0:
            band = Decimal(0)
        lines.append((band * rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    if ok:
        for fc in fixed:
            a = dec(fc.get("amount"))
            if a is None:
                ok = False
                break
            lines.append(a.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    if ok:
        subtotal = sum(lines, Decimal(0))
        if vat_rate is not None:
            vat = (subtotal * vat_rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            total = subtotal + vat

normal_kl = None
normal_avg = None
if history is not None:
    if str(history.get("account_number")) == str(bill.get("account_number")):
        vals = []
        for pb in history.get("previous_bills") or []:
            c = dec(pb.get("consumption_kl"))
            if c is not None:
                vals.append(c)
        if len(vals) >= 2:
            normal_avg = sum(vals, Decimal(0)) / Decimal(len(vals))
            normal_kl = normal_avg.quantize(Decimal("0.1"), rounding=ROUND_HALF_UP)

period_days = None
start = end = None
bp = bill.get("billing_period") or {}
try:
    start = date.fromisoformat(bp.get("start"))
    end = date.fromisoformat(bp.get("end"))
    period_days = (end - start).days + 1
except Exception:
    period_days = None

outage_days = None
if history is not None and start is not None and end is not None:
    dates = set()
    for o in history.get("outage_log") or []:
        if o.get("supply") == "none":
            try:
                d = date.fromisoformat(o.get("date"))
            except Exception:
                continue
            if start <= d <= end:
                dates.add(d)
    outage_days = len(dates)

supplied_days = None
if period_days is not None and outage_days is not None:
    supplied_days = period_days - outage_days

implied_kl = None
if normal_avg is not None and supplied_days is not None and period_days:
    implied_kl = (normal_avg * Decimal(supplied_days) / Decimal(period_days)).quantize(Decimal("0.1"), rounding=ROUND_HALF_UP)

out = {
    "subtotal": money(subtotal) if subtotal is not None else None,
    "vat": money(vat) if vat is not None else None,
    "total": money(total) if total is not None else None,
    "normal_kl": kl1(normal_kl) if normal_kl is not None else None,
    "period_days": period_days,
    "outage_days": outage_days,
    "supplied_days": supplied_days,
    "implied_kl": kl1(implied_kl) if implied_kl is not None else None,
}
print(json.dumps(out))
